package me.zinch.itmo.mts.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final XmlAccountStore store; public JwtAuthenticationFilter(JwtService jwt,XmlAccountStore store){this.jwt=jwt;this.store=store;}
 @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException {String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{SecurityAccount a=jwt.parse(h.substring(7),store);SecurityContextHolder.getContext().setAuthentication(UsernamePasswordAuthenticationToken.authenticated(a,null,RolePrivileges.authorities(a)));}catch(RuntimeException ignored){}c.doFilter(r,s);}}
